WITH t AS (
  SELECT c.customerid, c.segment, SUM(y.consumption) AS total
  FROM customers c JOIN yearmonth y ON y.customerid = c.customerid
  WHERE c.currency = 'CZK' AND c.segment IN ('SME','LAM','KAM') AND y.date LIKE '2013%'
  GROUP BY c.customerid, c.segment
), r AS (
  SELECT segment, customerid, total, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY total ASC, customerid ASC) rn
  FROM t
)
SELECT segment, customerid, total FROM r WHERE rn=1;

