WITH f AS (
  SELECT raceid, driverid, (split_part(fastestlaptime,':',1)::numeric*60 + split_part(fastestlaptime,':',2)::numeric)*1000 AS ms
  FROM results WHERE fastestlaptime LIKE '%:%'
),
r AS (
  SELECT raceid, driverid, ms, DENSE_RANK() OVER (PARTITION BY raceid ORDER BY ms) AS rk FROM f
)
SELECT COUNT(DISTINCT r.driverid) AS driver_count
FROM r JOIN drivers d USING (driverid)
WHERE r.rk = 2 AND d.dob >= '1976-01-01';

