WITH hs AS (
  SELECT ha.hero_id, ha.attribute_value FROM hero_attribute ha JOIN attribute a ON a.id = ha.attribute_id WHERE a.attribute_name = 'Strength'
),
hulk AS (
  SELECT hs.attribute_value FROM hs JOIN superhero s ON s.id = hs.hero_id WHERE s.superhero_name = 'Hulk'
