WITH cryo AS (
  SELECT DISTINCT hero_id FROM hero_power WHERE power_id = 19
),
shared AS (
  SELECT DISTINCT hp.hero_id FROM hero_power hp
  WHERE hp.power_id IN (SELECT hp2.power_id FROM hero_power hp2 WHERE hp2.hero_id IN (SELECT hero_id FROM cryo))
),
counts AS (
  SELECT hp.hero_id, COUNT(*) AS c FROM hero_power hp
  WHERE hp.hero_id IN (SELECT hero_id FROM shared)
  GROUP BY hp.hero_id
)
SELECT ROUND(AVG(c)::numeric, 1) AS avg_superpowers FROM counts;

